export const DOMAINS = [
  { key: "concepts", label: "Cloud Concepts", weightPct: 27 },
  { key: "architecture", label: "Azure Architecture & Services", weightPct: 37 },
  { key: "management", label: "Azure Management & Governance", weightPct: 36 },
];

const questions = [
  // ── CLOUD CONCEPTS (27) ──────────────────────────────────────────────────
  { id: 1, domain: "concepts", question: "A retail company's website normally handles light traffic but experiences huge, unpredictable spikes during flash sales. Which cloud benefit lets the app automatically add and remove compute resources to match demand in real time?", options: ["Elasticity", "Fault tolerance", "High availability", "Disaster recovery"], answer: 0, explanation: "Elasticity is the ability to automatically scale resources up or down to match real-time demand, so you pay only for what you actually use." },
  { id: 2, domain: "concepts", question: "What does 'scaling up' (vertical scaling) mean in cloud computing?", options: ["Adding more instances of a resource running in parallel", "Increasing the size or power of an existing resource, such as upgrading a VM to a larger size", "Moving a workload to a different region", "Reducing the number of resources to save cost"], answer: 1, explanation: "Scaling up (vertical scaling) means increasing the specifications of an existing resource, like adding more CPU or memory to one VM." },
  { id: 3, domain: "concepts", question: "What does 'scaling out' (horizontal scaling) mean in cloud computing?", options: ["Upgrading a single VM to a larger size", "Adding more instances of a resource, such as additional VMs, to share the load", "Migrating a workload to a private cloud", "Deleting unused resources"], answer: 1, explanation: "Scaling out (horizontal scaling) adds more instances of a resource, such as additional VMs behind a load balancer, to handle increased load." },
  { id: 4, domain: "concepts", question: "Which term describes a cloud system's ability to keep running, and recover quickly, when a component fails?", options: ["Elasticity", "Fault tolerance", "Agility", "Economy of scale"], answer: 1, explanation: "Fault tolerance is the ability of a system to remain operational even when one or more of its components fail." },
  { id: 5, domain: "concepts", question: "A company wants the ability to quickly get back up and running after a regional outage destroys a datacenter. Which cloud concept specifically addresses this?", options: ["Disaster recovery", "Elasticity", "Agility", "CapEx"], answer: 0, explanation: "Disaster recovery is the practice of preparing for and recovering from events that take down IT systems, such as a datacenter or region outage." },
  { id: 6, domain: "concepts", question: "Which term best describes the ability of a cloud provider to quickly develop, test, and bring new applications to market?", options: ["Agility", "Fault tolerance", "Redundancy", "CapEx"], answer: 0, explanation: "Agility refers to the speed at which cloud resources can be provisioned, letting organizations develop and deploy solutions much faster than with on-premises infrastructure." },
  { id: 7, domain: "concepts", question: "What does 'high availability' mean in the context of cloud computing?", options: ["A system is free to use", "A system runs for a designated period of time even when failures occur, meeting an agreed level of operational performance", "A system automatically adds resources during peak demand", "A system's cost decreases over time"], answer: 1, explanation: "High availability means a system is designed to be operational and accessible for a very high percentage of time, minimizing downtime." },
  { id: 8, domain: "concepts", question: "What is CapEx (capital expenditure)?", options: ["Ongoing operating costs paid as you use a service", "Upfront spending on physical infrastructure that is then depreciated over time", "The cost of software licensing only", "A tax credit for cloud usage"], answer: 1, explanation: "CapEx is the upfront money spent on physical infrastructure, such as buying servers, which is then deducted from tax obligations over the useful life of the asset (depreciation)." },
  { id: 9, domain: "concepts", question: "What is OpEx (operating expenditure)?", options: ["A one-time purchase of hardware", "Spending money on services or products now and being billed for them as you use them", "A discount for buying reserved capacity", "The physical cost of building a datacenter"], answer: 1, explanation: "OpEx is spending on services as they are consumed, such as a monthly cloud bill, and is typically deducted from taxes in the same year it is spent." },
  { id: 10, domain: "concepts", question: "A startup wants to avoid a large upfront investment in servers and instead pay only for the compute it consumes each month. Which financial model does this describe?", options: ["Moving from OpEx to CapEx", "Moving from CapEx to OpEx", "Reserved instance pricing only", "A fixed annual licensing fee"], answer: 1, explanation: "Cloud computing shifts spending from CapEx (buying hardware upfront) to OpEx (paying for consumption as you go), which is a key financial benefit of the cloud." },
  { id: 11, domain: "concepts", question: "What is the consumption-based (pay-as-you-go) pricing model?", options: ["A fixed price paid once per year regardless of usage", "A model where you pay only for the resources you use, with no upfront cost", "A model that requires a 3-year minimum commitment", "A model where the first year is always free"], answer: 1, explanation: "Consumption-based pricing means you pay only for the compute, storage, and other resources you actually consume, similar to a utility bill for electricity." },
  { id: 12, domain: "concepts", question: "Which of the following is NOT typically a benefit of cloud computing described by Microsoft?", options: ["High availability", "Scalability", "Guaranteed zero cost", "Agility"], answer: 2, explanation: "Cloud computing is not free; it follows a consumption-based pricing model. High availability, scalability, and agility are all well-known cloud benefits." },
  { id: 13, domain: "concepts", question: "What best describes Infrastructure as a Service (IaaS)?", options: ["The cloud provider manages everything including the application code", "You rent basic building blocks like virtual machines, storage, and networking, and manage the OS and applications yourself", "You only use a finished software product over the internet", "It is only available for on-premises datacenters"], answer: 1, explanation: "IaaS provides the fundamental building blocks — VMs, storage, networks — while you retain responsibility for the operating system, runtime, and applications. Azure Virtual Machines is a classic IaaS example." },
  { id: 14, domain: "concepts", question: "What best describes Platform as a Service (PaaS)?", options: ["You manage the physical servers yourself", "The provider manages the underlying infrastructure and runtime, letting you focus on developing and deploying your application code", "It is a fully finished application you use as-is", "It only supports a single programming language"], answer: 1, explanation: "PaaS provides a managed environment for building, testing, and deploying applications without worrying about the underlying servers, OS patching, or runtime. Azure App Service is a common PaaS example." },
  { id: 15, domain: "concepts", question: "What best describes Software as a Service (SaaS)?", options: ["A fully developed application that is managed entirely by the provider and consumed by end users, typically via a browser", "A set of raw virtual machines you configure yourself", "A service that only provides storage", "A model where you must install and patch the software locally"], answer: 0, explanation: "SaaS delivers a complete, ready-to-use application over the internet, with the provider handling all maintenance, updates, and infrastructure. Microsoft 365 and Outlook on the web are SaaS examples." },
  { id: 16, domain: "concepts", question: "A company wants full control over the operating system and needs to install custom, legacy software that requires specific OS-level configuration. Which cloud service model is the best fit?", options: ["SaaS", "IaaS", "Function as a Service only", "None of the above"], answer: 1, explanation: "IaaS gives you the most control, including full access to configure the operating system, which is necessary for legacy or highly customized software." },
  { id: 17, domain: "concepts", question: "A development team wants to deploy a web application quickly without managing servers, operating systems, or patching, while still writing custom application code. Which service model fits best?", options: ["IaaS", "PaaS", "SaaS", "On-premises hosting"], answer: 1, explanation: "PaaS removes the burden of managing infrastructure and OS patching, letting developers focus purely on writing and deploying application code." },
  { id: 18, domain: "concepts", question: "Which statement correctly ranks the service models by how much management responsibility is shifted to the cloud provider, from least to most?", options: ["SaaS, PaaS, IaaS", "IaaS, PaaS, SaaS", "PaaS, IaaS, SaaS", "IaaS, SaaS, PaaS"], answer: 1, explanation: "IaaS shifts the least responsibility to the provider (you manage OS and apps), PaaS shifts more (provider manages OS/runtime), and SaaS shifts the most (provider manages everything)." },
  { id: 19, domain: "concepts", question: "What is a public cloud deployment model?", options: ["Infrastructure owned and run exclusively by a single organization on its own premises", "Services offered over the public internet and shared across multiple organizations, owned and operated by a third-party cloud provider", "A model with no internet connectivity", "A model reserved only for government use"], answer: 1, explanation: "In the public cloud model, a third-party provider (like Microsoft) owns the hardware and delivers services to multiple customers over the public internet." },
  { id: 20, domain: "concepts", question: "What is a private cloud deployment model?", options: ["Cloud services shared by the general public", "Computing resources used exclusively by a single business or organization, which can be hosted on-premises or by a third party", "A free tier of a public cloud", "A cloud with no security controls"], answer: 1, explanation: "A private cloud is dedicated entirely to one organization, offering more control and customization, though the organization bears more of the management responsibility." },
  { id: 21, domain: "concepts", question: "A financial services company must keep sensitive customer records on infrastructure it fully controls for regulatory reasons, but wants to run its public-facing website in the public cloud for scalability. Which deployment model fits this scenario?", options: ["Public cloud only", "Private cloud only", "Hybrid cloud", "Community cloud"], answer: 2, explanation: "Hybrid cloud combines public and private cloud environments, allowing sensitive workloads to remain on private infrastructure while other workloads take advantage of public cloud scalability." },
  { id: 22, domain: "concepts", question: "What is a key advantage of the hybrid cloud model?", options: ["It eliminates all cloud costs", "It lets organizations keep sensitive data or legacy systems on-premises while still benefiting from public cloud scale and services", "It requires no networking configuration between environments", "It is only available to government agencies"], answer: 1, explanation: "Hybrid cloud provides flexibility to place workloads where they make the most sense, balancing compliance, latency, or legacy requirements against the scalability of the public cloud." },
  { id: 23, domain: "concepts", question: "What does 'economies of scale' mean in the context of cloud providers like Microsoft Azure?", options: ["Prices increase as more customers use the service", "Costs per unit decrease as the cloud provider buys and operates hardware at a massive scale, and those savings are passed to customers", "Every customer pays a fixed monthly fee regardless of size", "Only large enterprises benefit from cloud pricing"], answer: 1, explanation: "Because cloud providers purchase and operate resources at enormous scale, their per-unit costs drop, and those savings are generally passed on to customers through lower prices." },
  { id: 24, domain: "concepts", question: "Which of the following best illustrates the 'global reach' benefit of public cloud computing?", options: ["An application can be deployed to datacenters around the world to reduce latency for users in different regions", "All data must be stored in a single datacenter", "Cloud resources cannot cross international borders", "Global reach only applies to storage services"], answer: 0, explanation: "Public cloud providers operate datacenters across many geographic regions, letting organizations deploy applications closer to their users worldwide to reduce latency." },
  { id: 25, domain: "concepts", question: "Under the shared responsibility model, which party is always responsible for the physical security of the datacenter, regardless of the service model (IaaS, PaaS, or SaaS)?", options: ["The customer", "The cloud provider (e.g., Microsoft)", "A third-party auditor", "No one; it is not managed"], answer: 1, explanation: "In the shared responsibility model, the cloud provider is always responsible for the physical security of the datacenter and underlying hardware, no matter which service model is used." },
  { id: 26, domain: "concepts", question: "Under the shared responsibility model, as you move from IaaS to PaaS to SaaS, what generally happens to the customer's share of responsibility?", options: ["It increases", "It decreases, as the provider takes on more of the management burden", "It stays exactly the same", "Responsibility disappears entirely in SaaS"], answer: 1, explanation: "As you move from IaaS toward SaaS, the cloud provider takes on more responsibility (patching, runtime, application maintenance), while the customer's responsibility decreases, though the customer is still always responsible for their own data and access control." },
  { id: 27, domain: "concepts", question: "A company currently spends heavily on maintaining an aging on-premises datacenter, including hardware refresh cycles and physical security staff. Moving to the cloud primarily changes this spending in which way?", options: ["It has no financial effect at all", "It converts large, upfront CapEx investments into ongoing, predictable OpEx based on consumption", "It doubles the total cost with no benefit", "It eliminates the need to ever pay for compute"], answer: 1, explanation: "One of the core financial benefits of cloud adoption is shifting spending from capital expenditure on owned hardware to operating expenditure that scales with actual usage." },

  // ── AZURE ARCHITECTURE & SERVICES (37) ──────────────────────────────────
  { id: 28, domain: "architecture", question: "What is an Azure region?", options: ["A single physical building housing all Azure hardware worldwide", "A geographical area on the planet containing at least one datacenter, connected via a low-latency network", "A logical container for billing only", "A synonym for an Azure subscription"], answer: 1, explanation: "An Azure region is a set of datacenters in a specific geographic location, networked together with low latency, that customers can choose to deploy resources into." },
  { id: 29, domain: "architecture", question: "What is a region pair in Azure?", options: ["Two unrelated regions chosen at random by the customer", "Two regions within the same geography that are combined to provide cross-region disaster recovery and are updated at different times", "A pair of virtual machines in the same datacenter", "Two subscriptions linked for billing"], answer: 1, explanation: "Azure pairs regions within the same geography (at least 300 miles apart when possible) so that planned Azure updates are rolled out sequentially, and one region can be used for disaster recovery of the other." },
  { id: 30, domain: "architecture", question: "What is an Azure Availability Zone?", options: ["A separate Azure subscription for testing", "A physically separate datacenter (or set of datacenters) within an Azure region, each with independent power, cooling, and networking", "A firewall rule applied to a virtual network", "A backup copy of a resource group"], answer: 1, explanation: "Availability zones are physically separate locations within a region, each with independent power, cooling, and networking, used to protect applications from datacenter-level failures." },
  { id: 31, domain: "architecture", question: "A company wants to protect its application against the failure of an entire datacenter, while keeping it within the same Azure region for low latency. Which feature should it use?", options: ["Region pairs", "Availability zones", "A different subscription", "Resource locks"], answer: 1, explanation: "Availability zones let you spread resources across physically separate datacenters within the same region, protecting against a single datacenter failure while keeping latency low." },
  { id: 32, domain: "architecture", question: "What is an Azure resource group?", options: ["A billing agreement between Microsoft and a customer", "A logical container used to group and manage related Azure resources together", "A physical datacenter", "A type of virtual machine"], answer: 1, explanation: "A resource group is a logical container that holds related resources for an Azure solution, making it easier to manage, monitor, and apply policies or role assignments as a group." },
  { id: 33, domain: "architecture", question: "What is an Azure subscription primarily used for?", options: ["Grouping virtual networks only", "Acting as a billing and access-control boundary that links to an Azure account and defines usage limits", "Storing blob data", "Running scheduled scripts"], answer: 1, explanation: "An Azure subscription is a logical unit that ties resource usage to billing, and it also serves as a boundary for applying access controls and quotas." },
  { id: 34, domain: "architecture", question: "What is the purpose of an Azure management group?", options: ["To store files shared across VMs", "To organize multiple subscriptions into a hierarchy so governance conditions like policies can be applied across all of them at once", "To replace the need for resource groups", "To manage individual virtual machine disks"], answer: 1, explanation: "Management groups sit above subscriptions in the hierarchy and let organizations apply governance controls, such as Azure Policy, consistently across many subscriptions at once." },
  { id: 35, domain: "architecture", question: "Which of the following correctly describes the Azure resource hierarchy from the top level down?", options: ["Resource groups → subscriptions → management groups → resources", "Management groups → subscriptions → resource groups → resources", "Resources → resource groups → management groups → subscriptions", "Subscriptions → management groups → resources → resource groups"], answer: 1, explanation: "The hierarchy flows from management groups at the top, down to subscriptions, then resource groups, and finally the individual resources themselves." },
  { id: 36, domain: "architecture", question: "What is Azure Resource Manager (ARM)?", options: ["A physical device that manages datacenter cooling", "The deployment and management service for Azure that provides a consistent management layer to create, update, and delete resources", "A billing report generated monthly", "A type of virtual network gateway"], answer: 1, explanation: "Azure Resource Manager (ARM) is the front end for all requests to Azure, whether from the portal, CLI, PowerShell, or SDKs, and it provides consistent management capabilities like tagging, RBAC, and policy enforcement." },
  { id: 37, domain: "architecture", question: "What is an ARM template?", options: ["A pre-configured virtual machine image", "A JSON file that defines the infrastructure and configuration for a deployment, enabling infrastructure as code", "A spreadsheet used for cost estimation", "A support ticket format"], answer: 1, explanation: "ARM templates are JSON files that declaratively define the resources to deploy, allowing infrastructure as code so deployments are consistent and repeatable." },
  { id: 38, domain: "architecture", question: "What is a key benefit of deploying resources with ARM templates instead of manually through the Azure portal?", options: ["Templates are always cheaper to run", "Deployments become repeatable, consistent, and can be version-controlled and reviewed like code", "Templates eliminate the need for a subscription", "Templates automatically fix application bugs"], answer: 1, explanation: "Because ARM templates are declarative code, they can be stored in source control, reused, and repeatedly deployed to produce the exact same environment every time, reducing human error." },
  { id: 39, domain: "architecture", question: "Which Azure compute service provides on-demand, scalable virtualized servers where you manage the operating system yourself?", options: ["Azure Functions", "Azure Virtual Machines", "Azure App Service", "Azure Blob Storage"], answer: 1, explanation: "Azure Virtual Machines (VMs) is an IaaS offering that gives you full control over the guest operating system and installed software." },
  { id: 40, domain: "architecture", question: "What is the purpose of Azure Virtual Machine Scale Sets?", options: ["To store static website content", "To let you create and manage a group of identical, load-balanced VMs that can automatically increase or decrease in number based on demand", "To back up a single VM", "To provide DNS resolution"], answer: 1, explanation: "VM Scale Sets manage a group of identical VMs, automatically scaling the number of instances out or in based on demand or a defined schedule." },
  { id: 41, domain: "architecture", question: "What is Azure App Service best suited for?", options: ["Running arbitrary command-line scripts on a schedule", "Hosting web applications, REST APIs, and mobile backends as a fully managed PaaS offering", "Managing physical network switches", "Storing large binary files"], answer: 1, explanation: "Azure App Service is a PaaS offering for building and hosting web apps, APIs, and mobile backends without managing the underlying infrastructure." },
  { id: 42, domain: "architecture", question: "A developer needs to quickly run a single containerized task without setting up a full orchestration platform. Which Azure service is the simplest fit?", options: ["Azure Kubernetes Service (AKS)", "Azure Container Instances (ACI)", "Azure Virtual Machine Scale Sets", "Azure Virtual Desktop"], answer: 1, explanation: "Azure Container Instances (ACI) is designed for fast, simple deployment of individual containers without needing to provision or manage a cluster." },
  { id: 43, domain: "architecture", question: "Which Azure service provides a fully managed platform for deploying, scaling, and orchestrating containerized applications using Kubernetes?", options: ["Azure Container Instances", "Azure Kubernetes Service (AKS)", "Azure Functions", "Azure App Service"], answer: 1, explanation: "Azure Kubernetes Service (AKS) simplifies deploying and managing containerized applications by providing a managed Kubernetes cluster." },
  { id: 44, domain: "architecture", question: "What is Azure Virtual Desktop (formerly Windows Virtual Desktop) used for?", options: ["Hosting static websites", "Providing a virtualized Windows desktop and application experience that users can access remotely from any device", "Running Kubernetes clusters", "Storing files in the cloud"], answer: 1, explanation: "Azure Virtual Desktop delivers a full virtual desktop and app experience, allowing organizations to provide remote, managed desktops to employees from virtually any device." },
  { id: 45, domain: "architecture", question: "What best describes Azure Functions?", options: ["A service for storing relational databases", "An event-driven, serverless compute service that runs small pieces of code in response to triggers, without you managing servers", "A tool for managing virtual networks", "A dedicated physical server offering"], answer: 1, explanation: "Azure Functions is a serverless compute service that executes code in response to events or triggers, automatically scaling and charging only for actual execution time." },
  { id: 46, domain: "architecture", question: "A company needs to run a small piece of code only when a new file is uploaded to storage, without provisioning or paying for idle servers. Which service is the best fit?", options: ["Azure Virtual Machines", "Azure Functions", "Azure Virtual Machine Scale Sets", "Azure Virtual Desktop"], answer: 1, explanation: "Azure Functions is ideal for event-driven, on-demand workloads since it runs code only when triggered and bills based on execution, not idle time." },
  { id: 47, domain: "architecture", question: "What is an Azure Virtual Network (VNet) primarily used for?", options: ["Storing blob data", "Providing a private, isolated network in Azure where resources like VMs can securely communicate with each other, the internet, and on-premises networks", "Running containerized applications", "Managing billing across subscriptions"], answer: 1, explanation: "A VNet is the fundamental building block for private networking in Azure, enabling secure communication between Azure resources, the internet, and on-premises networks." },
  { id: 48, domain: "architecture", question: "What does VNet peering allow you to do?", options: ["Connect two virtual networks so resources in each can communicate as if they were on the same network", "Encrypt data at rest in a storage account", "Automatically scale virtual machines", "Grant users access to the Azure portal"], answer: 0, explanation: "VNet peering connects two virtual networks, seamlessly routing traffic between them using the Microsoft backbone network, without needing a gateway or public internet." },
  { id: 49, domain: "architecture", question: "Which Azure networking service creates an encrypted connection over the public internet between an on-premises network and Azure?", options: ["ExpressRoute", "VPN Gateway", "Azure DNS", "Azure Load Balancer"], answer: 1, explanation: "VPN Gateway establishes a secure, encrypted tunnel over the public internet to connect on-premises networks to Azure virtual networks." },
  { id: 50, domain: "architecture", question: "A large enterprise needs a private, dedicated connection to Azure that does not travel over the public internet, offering higher reliability, lower latency, and higher throughput than a VPN. Which service should it use?", options: ["VPN Gateway", "ExpressRoute", "VNet peering", "Azure DNS"], answer: 1, explanation: "ExpressRoute provides a private, dedicated connection between on-premises infrastructure and Azure through a connectivity provider, bypassing the public internet entirely." },
  { id: 51, domain: "architecture", question: "What is the primary function of Azure DNS?", options: ["Providing load balancing across VMs", "Hosting domain names and resolving them to IP addresses using Microsoft's global network of name servers", "Encrypting network traffic", "Storing virtual machine disks"], answer: 1, explanation: "Azure DNS is a hosting service for DNS domains that resolves domain names to IP addresses, using Microsoft's fast, globally distributed infrastructure." },
  { id: 52, domain: "architecture", question: "A company needs to distribute incoming HTTP traffic across multiple web servers based on URL path, and also wants Web Application Firewall capabilities. Which Azure service is designed for this Layer 7 (application layer) scenario, as opposed to simple Layer 4 balancing?", options: ["Azure Load Balancer", "Azure Application Gateway", "Azure ExpressRoute", "Azure Bastion"], answer: 1, explanation: "Azure Application Gateway operates at Layer 7 (HTTP/HTTPS), supporting URL-based routing and a Web Application Firewall, while Azure Load Balancer works at Layer 4 (TCP/UDP) for simpler traffic distribution." },
  { id: 53, domain: "architecture", question: "What is an Azure storage account?", options: ["A user login for the Azure portal", "A container that provides a unique namespace for storing and accessing your data objects, such as blobs, files, queues, and tables", "A billing subscription tier", "A virtual machine image"], answer: 1, explanation: "A storage account is the top-level resource that provides access to Azure Storage services like Blob storage, File storage, Queue storage, and Table storage." },
  { id: 54, domain: "architecture", question: "Which Azure Blob Storage access tier is designed for data that is accessed frequently?", options: ["Archive", "Cool", "Hot", "Premium SSD"], answer: 2, explanation: "The Hot tier is optimized for data that is accessed frequently and offers the lowest access cost but the highest storage cost of the standard tiers." },
  { id: 55, domain: "architecture", question: "A company must retain years of compliance data that is almost never accessed but must not be deleted, and wants to minimize storage cost above all else, accepting hours of retrieval latency if needed. Which Blob Storage tier fits best?", options: ["Hot", "Cool", "Archive", "Premium"], answer: 2, explanation: "The Archive tier offers the lowest storage cost, but data must be 'rehydrated' before it can be accessed, which can take hours — ideal for rarely accessed, long-term compliance data." },
  { id: 56, domain: "architecture", question: "What are Azure managed disks used for?", options: ["Storing unstructured web content accessed via a URL", "Providing persistent, block-level storage volumes for use with Azure Virtual Machines, with the storage management handled by Azure", "Hosting DNS zones", "Running serverless functions"], answer: 1, explanation: "Managed disks are virtual hard disks used by VMs, where Azure handles the underlying storage account management, redundancy, and scaling automatically." },
  { id: 57, domain: "architecture", question: "What is Azure Files primarily used for?", options: ["Running virtual machines", "Providing fully managed file shares accessible via the industry-standard SMB protocol, mountable simultaneously by cloud or on-premises deployments", "Hosting a relational database", "Load balancing web traffic"], answer: 1, explanation: "Azure Files offers fully managed cloud file shares accessible via SMB (and NFS), allowing multiple VMs or on-premises machines to mount the same share concurrently." },
  { id: 58, domain: "architecture", question: "What does LRS (Locally Redundant Storage) do?", options: ["Replicates your data across three availability zones in a region", "Replicates your data three times within a single datacenter in one region", "Replicates your data to a secondary, geographically distant region", "Replicates data across two separate Azure subscriptions"], answer: 1, explanation: "LRS keeps three synchronous copies of your data within a single datacenter, protecting against hardware failures but not datacenter-level disasters." },
  { id: 59, domain: "architecture", question: "What does ZRS (Zone-Redundant Storage) provide that LRS does not?", options: ["Replication to a different country", "Synchronous replication of data across three availability zones within a single region, protecting against a datacenter failure", "Free data transfer", "Automatic virtual machine failover"], answer: 1, explanation: "ZRS replicates data synchronously across three availability zones in a region, so your data survives even if a single datacenter becomes unavailable, unlike LRS which only protects within one datacenter." },
  { id: 60, domain: "architecture", question: "What does GRS (Geo-Redundant Storage) provide?", options: ["Data is copied three times within one datacenter only", "Data is replicated to a secondary, geographically distant paired region, in addition to being replicated locally in the primary region", "Data is deleted automatically after 30 days", "Data is only ever stored in a single availability zone"], answer: 1, explanation: "GRS copies data to a secondary region hundreds of miles away, in addition to keeping three copies in the primary region, protecting against a full regional outage." },
  { id: 61, domain: "architecture", question: "What additional capability does RA-GRS (Read-Access Geo-Redundant Storage) add compared to standard GRS?", options: ["It replicates data to three regions instead of two", "It allows read access to the data in the secondary region, even when the primary region is fully available", "It removes the need for a storage account", "It automatically encrypts data with customer-managed keys"], answer: 1, explanation: "RA-GRS provides everything GRS does, plus read-only access to the replicated data in the secondary region at any time, which can improve availability for read-heavy applications." },
  { id: 62, domain: "architecture", question: "What is Microsoft Entra ID (formerly Azure Active Directory)?", options: ["A storage service for unstructured data", "A cloud-based identity and access management service used to authenticate and authorize users and manage directory objects", "A networking service for connecting VNets", "A tool for estimating Azure costs"], answer: 1, explanation: "Microsoft Entra ID is Microsoft's cloud-based identity service, providing authentication and access management for resources such as Microsoft 365 and other cloud apps." },
  { id: 63, domain: "architecture", question: "What is the difference between authentication and authorization?", options: ["They are two names for the exact same process", "Authentication verifies who a user is, while authorization determines what that verified user is allowed to do", "Authorization verifies identity, while authentication grants permissions", "Authentication only applies to devices, not users"], answer: 1, explanation: "Authentication (AuthN) is the process of proving your identity, typically with a username and password or biometrics. Authorization (AuthZ) determines the resources and actions the authenticated identity is permitted to access." },
  { id: 64, domain: "architecture", question: "What is Multi-Factor Authentication (MFA)?", options: ["A process requiring two or more separate forms of verification before granting access, such as a password plus a code sent to a phone", "A method that allows access with only a username", "A type of firewall rule", "A billing feature for large subscriptions"], answer: 0, explanation: "MFA strengthens security by requiring users to provide at least two different types of verification evidence, greatly reducing the risk from a stolen password alone." },
  { id: 65, domain: "architecture", question: "What is Azure Conditional Access used for?", options: ["Automatically resizing virtual machines", "Enforcing access controls based on conditions such as user location, device state, or risk level before granting access to resources", "Managing DNS zones", "Estimating monthly cloud spend"], answer: 1, explanation: "Conditional Access lets organizations define policies that require certain conditions — like a trusted location or compliant device — to be met before access is granted, or to require extra verification such as MFA." },
  { id: 66, domain: "architecture", question: "What is the key difference between Azure role-based access control (RBAC) and Microsoft Entra roles?", options: ["They are identical and interchangeable", "Azure RBAC manages access to Azure resources (like VMs or storage), while Entra roles manage access to Entra ID directory-level tasks (like resetting user passwords)", "Entra roles only apply to storage accounts", "RBAC only works with Microsoft 365 licenses"], answer: 1, explanation: "Azure RBAC controls permissions over Azure resources such as resource groups and VMs, while Microsoft Entra roles control administrative permissions over the directory itself, such as user and group management." },

  // ── AZURE MANAGEMENT & GOVERNANCE (36) ──────────────────────────────────
  { id: 67, domain: "management", question: "What is the Azure Pricing Calculator used for?", options: ["Comparing the total cost of running an on-premises datacenter versus Azure over several years", "Estimating the cost of Azure products and services before you deploy them", "Automatically applying discounts to an existing subscription", "Enforcing tagging policies on resources"], answer: 1, explanation: "The Pricing Calculator is a free web tool that lets you configure and estimate the cost of Azure products and services before committing to a deployment." },
  { id: 68, domain: "management", question: "What is the purpose of the Total Cost of Ownership (TCO) Calculator?", options: ["To estimate the price of a single virtual machine SKU", "To help estimate the cost savings of migrating a workload from on-premises infrastructure to Azure", "To enforce naming conventions on resources", "To calculate an employee's salary"], answer: 1, explanation: "The TCO Calculator compares the cost of running your infrastructure on-premises against running the equivalent workload in Azure, helping build a business case for migration." },
  { id: 69, domain: "management", question: "What does Azure Cost Management + Billing help you do?", options: ["Deploy virtual machines automatically", "Monitor, allocate, and optimize the cost of your Azure resources after they are deployed", "Configure network security groups", "Manage user identities"], answer: 1, explanation: "Cost Management + Billing provides tools to analyze costs, view billing information, set budgets, and get recommendations for optimizing spend across your Azure environment." },
  { id: 70, domain: "management", question: "A finance team wants to be automatically notified by email when Azure spending is projected to exceed a set monthly amount. What should they configure?", options: ["An Azure Policy assignment", "A budget with an alert in Azure Cost Management", "A resource lock", "An availability zone"], answer: 1, explanation: "Budgets in Azure Cost Management let you set spending thresholds and configure alerts that notify stakeholders when actual or forecasted costs approach or exceed those thresholds." },
  { id: 71, domain: "management", question: "Which factors commonly affect the price of Azure resources?", options: ["Only the number of employees in the company", "Resource type, region/location, consumption/bandwidth, and subscription type", "Only the time of year the resources were created", "The color scheme chosen in the Azure portal"], answer: 1, explanation: "Azure pricing depends on multiple factors including the specific resource type and size, the region deployed to, the amount of usage/bandwidth consumed, and the subscription or offer type." },
  { id: 72, domain: "management", question: "How does Azure typically charge for network bandwidth?", options: ["All inbound and outbound data transfer is always free", "Inbound data transfer is generally free, while outbound (egress) data transfer is typically billed", "All bandwidth is billed at a single flat global rate regardless of direction", "Bandwidth charges apply only to storage accounts"], answer: 1, explanation: "In general, data moving into Azure (ingress) is free, while data moving out of Azure to the internet (egress) incurs a charge, which is an important consideration for cost estimation." },
  { id: 73, domain: "management", question: "What is Azure Policy used for?", options: ["Estimating the cost of future deployments", "Creating, assigning, and enforcing rules and effects over resources so they stay compliant with corporate standards", "Granting users permission to manage resources", "Monitoring the health of Azure datacenters"], answer: 1, explanation: "Azure Policy evaluates resources against defined business rules (such as allowed regions or required tags) and can audit, deny, or even automatically remediate non-compliant resources." },
  { id: 74, domain: "management", question: "A company must ensure that no employee can accidentally deploy a virtual machine in a region outside of the approved list. Which Azure governance tool should be used?", options: ["Azure Advisor", "Azure Policy", "Azure Monitor", "Resource tags"], answer: 1, explanation: "Azure Policy can enforce rules such as restricting allowed deployment regions, denying or flagging any resource creation that violates the defined policy." },
  { id: 75, domain: "management", question: "What is the main difference between Azure Policy and Azure role-based access control (RBAC)?", options: ["They do exactly the same thing", "RBAC controls what actions a user is allowed to perform, while Azure Policy controls the properties and configuration that resources must comply with, regardless of who created them", "Azure Policy manages user sign-in, while RBAC manages resource cost", "RBAC only applies to storage accounts"], answer: 1, explanation: "RBAC focuses on user permissions (who can do what), while Azure Policy focuses on resource compliance (what properties or configurations are and are not allowed), independent of who is making the change." },
  { id: 76, domain: "management", question: "What does a 'CanNotDelete' resource lock do?", options: ["Prevents anyone, including owners, from reading the resource", "Allows authorized users to read and modify a resource, but prevents it from being deleted", "Prevents any changes, including modifications and deletions", "Automatically deletes unused resources after 30 days"], answer: 1, explanation: "A CanNotDelete lock allows the resource to still be read and modified, but blocks deletion, helping to prevent accidental removal of critical resources." },
  { id: 77, domain: "management", question: "What does a 'ReadOnly' resource lock do?", options: ["Prevents deletion only, while modifications remain allowed", "Restricts all users to only reading the resource, preventing both edits and deletion", "Grants full administrator access to all users", "Only applies to storage accounts, not other resource types"], answer: 1, explanation: "A ReadOnly lock is the most restrictive lock type: it prevents any modification or deletion of a resource, allowing only read operations." },
  { id: 78, domain: "management", question: "A team accidentally deleted a critical production database last month. Which Azure governance feature would have best prevented this from happening again?", options: ["A resource tag", "A resource lock set to CanNotDelete", "An Azure Advisor recommendation", "A budget alert"], answer: 1, explanation: "Applying a CanNotDelete resource lock would have blocked the deletion action while still allowing normal read and update operations on the resource." },
  { id: 79, domain: "management", question: "What are Azure tags used for?", options: ["Encrypting data at rest", "Attaching custom name-value metadata to resources to organize them for billing, management, or automation purposes", "Granting network access between VNets", "Scaling virtual machines automatically"], answer: 1, explanation: "Tags are key-value pairs applied to resources that let you logically categorize them, such as by department, environment, or cost center, which is especially useful for cost reporting." },
  { id: 80, domain: "management", question: "A company wants to break down its monthly Azure bill by department (Marketing, Engineering, Sales) even though resources for all departments exist in the same subscription. What is the simplest way to achieve this?", options: ["Create a separate management group for each department", "Apply a 'department' tag to each resource and then filter cost reports by that tag", "Create a resource lock for each department", "This is not possible in Azure"], answer: 1, explanation: "Tags let you attach metadata such as a department name to resources, and Cost Management reports can then be filtered or grouped by those tags to break down spend accordingly." },
  { id: 81, domain: "management", question: "What is Azure Blueprints (now largely succeeded by Template Specs and Deployment Stacks, but still a core AZ-900 concept) used for?", options: ["Estimating hardware costs for on-premises servers", "Defining a repeatable set of Azure resources, policies, and role assignments that implement and adhere to an organization's standards and compliance requirements", "Monitoring the health of Azure services globally", "Replacing the need for a subscription"], answer: 1, explanation: "Azure Blueprints packages together artifacts like ARM templates, policy assignments, and RBAC role assignments into a single definition, so new environments can be provisioned that automatically meet organizational and compliance standards." },
  { id: 82, domain: "management", question: "What is Azure Monitor used for?", options: ["Only monitoring the physical temperature of Microsoft's datacenters", "Collecting, analyzing, and acting on telemetry (metrics and logs) from cloud and on-premises environments to maximize performance and availability", "Estimating future billing costs", "Managing user sign-in credentials"], answer: 1, explanation: "Azure Monitor is a comprehensive solution for collecting, analyzing, and responding to monitoring data (metrics, logs, and traces) across applications and infrastructure." },
  { id: 83, domain: "management", question: "What is Azure Log Analytics primarily used for?", options: ["Deploying virtual machines", "Editing and running queries, using Kusto Query Language (KQL), against log data collected by Azure Monitor", "Configuring network peering", "Setting spending budgets"], answer: 1, explanation: "Log Analytics is the tool within Azure Monitor used to write and execute log queries (in KQL) to analyze data collected from monitored resources." },
  { id: 84, domain: "management", question: "What does Azure Advisor provide?", options: ["A real-time list of ongoing Azure service outages", "Personalized recommendations across cost, security, reliability, operational excellence, and performance to help optimize your Azure deployments", "A calculator for total cost of ownership", "A tool for locking resources against deletion"], answer: 1, explanation: "Azure Advisor continuously analyzes your resource configuration and usage telemetry to provide tailored recommendations in five categories: cost, security, reliability, operational excellence, and performance." },
  { id: 85, domain: "management", question: "What is the purpose of Azure Service Health?", options: ["To show the general public status of Azure services worldwide, without personalization", "To provide a personalized view of the health of the specific Azure services and regions your resources actually use, including planned maintenance and outages", "To calculate the price of new resources", "To enforce naming conventions"], answer: 1, explanation: "Service Health gives you a personalized dashboard and alerts about service issues, planned maintenance, and health advisories that specifically affect the Azure resources and regions you use." },
  { id: 86, domain: "management", question: "What is the difference between Azure Status and Azure Service Health?", options: ["They are the same page with two different names", "Azure Status shows the global, public health of all Azure services, while Service Health is personalized to show only the services and regions relevant to your subscriptions", "Azure Status is personalized, while Service Health is public", "Service Health only covers billing issues"], answer: 1, explanation: "Azure Status (status.azure.com) is a public page showing the overall health of Azure services globally, whereas Service Health (in the Azure portal) is tailored to alert you specifically about issues affecting the resources you use." },
  { id: 87, domain: "management", question: "Which tool provides a graphical, browser-based interface for creating, managing, and monitoring Azure resources?", options: ["Azure CLI", "Azure Portal", "Azure PowerShell", "Azure Cloud Shell only"], answer: 1, explanation: "The Azure Portal is a web-based, graphical user interface for managing your Azure subscription and resources, accessible from any browser." },
  { id: 88, domain: "management", question: "What is the Azure CLI?", options: ["A graphical desktop application only available on Windows", "A cross-platform command-line tool for managing Azure resources using text-based commands, often used for scripting and automation", "A mobile app for viewing alerts", "A billing report generator"], answer: 1, explanation: "The Azure CLI is a cross-platform (Windows, macOS, Linux) command-line tool that lets administrators and developers manage Azure resources using commands, well suited to scripting and automation." },
  { id: 89, domain: "management", question: "What is Azure PowerShell?", options: ["A REST API only", "A module of cmdlets for managing Azure resources directly from the PowerShell command-line shell and scripting environment", "A graphical portal accessible only on mobile devices", "A pricing calculator"], answer: 1, explanation: "Azure PowerShell provides a set of cmdlets that let you manage Azure resources from the PowerShell environment, useful for administrators already familiar with PowerShell scripting." },
  { id: 90, domain: "management", question: "What is Azure Cloud Shell?", options: ["A physical server rack located in an Azure datacenter", "A browser-based, authenticated shell environment (offering a choice of Bash or PowerShell) for managing Azure resources without installing anything locally", "A tool exclusively for managing on-premises servers", "A type of virtual machine size"], answer: 1, explanation: "Azure Cloud Shell is an interactive, browser-accessible shell that lets you choose between Bash or PowerShell to manage Azure resources, with tools pre-installed and no local setup required." },
  { id: 91, domain: "management", question: "An administrator wants to run Azure CLI commands directly from a browser on a locked-down machine where installing software is not allowed. Which tool should they use?", options: ["Azure PowerShell installed locally", "Azure Cloud Shell", "Azure Advisor", "Azure Blueprints"], answer: 1, explanation: "Azure Cloud Shell runs entirely in the browser and requires no local installation, making it ideal for managing Azure resources from any device, including restricted machines." },
  { id: 92, domain: "management", question: "What is Azure Arc used for?", options: ["Only managing resources that are physically located in Azure datacenters", "Extending Azure management capabilities, such as policies and monitoring, to resources running on-premises, in other clouds, or at the edge", "Replacing the need for virtual networks", "Automatically translating on-premises licenses to Azure Reservations"], answer: 1, explanation: "Azure Arc extends the Azure management plane so that servers, Kubernetes clusters, and other resources outside of Azure — on-premises or in other clouds — can be managed, governed, and monitored as if they were native Azure resources." },
  { id: 93, domain: "management", question: "A company has servers running in its own datacenter as well as in another cloud provider, and wants to apply consistent Azure Policy rules and monitoring across all of them from a single place. Which Azure service enables this?", options: ["Azure Arc", "Azure Bastion", "Azure DNS", "Azure Files"], answer: 0, explanation: "Azure Arc lets you project non-Azure resources, including on-premises servers and resources in other clouds, into Azure Resource Manager so they can be governed and monitored alongside native Azure resources." },
  { id: 94, domain: "management", question: "What can the Azure mobile app be used for?", options: ["Writing and deploying ARM templates only", "Monitoring resource health, checking alerts, and performing basic management tasks on Azure resources from a smartphone or tablet", "Replacing the need for a subscription entirely", "Running full PowerShell scripts natively"], answer: 1, explanation: "The Azure mobile app lets you monitor the status and health of your Azure resources, respond to alerts, and perform simple management actions from a mobile device." },
  { id: 95, domain: "management", question: "What does a Service Level Agreement (SLA) define?", options: ["The exact code used to build a service", "A commitment from Microsoft about measurable metrics like uptime and connectivity for a given Azure service", "The list of employees who can access a resource", "A schedule for hardware replacement"], answer: 1, explanation: "An SLA is a formal agreement that defines the performance and availability commitments Microsoft makes for a service, such as guaranteeing a certain percentage of uptime." },
  { id: 96, domain: "management", question: "If you combine two independent Azure services that each have a 99.9% SLA, and your application depends on both being available, what happens to the composite (overall) SLA?", options: ["It increases to 99.99%", "It decreases, because the overall availability is the product of both SLAs (approximately 99.8%)", "It stays exactly at 99.9%", "SLAs cannot be combined mathematically"], answer: 1, explanation: "When an application depends on multiple services in sequence, the composite SLA is generally the product of the individual SLAs, which lowers the overall guaranteed availability unless redundancy is added." },
  { id: 97, domain: "management", question: "What is a subscription 'spending limit' in the context of a free or pay-as-you-go trial Azure account?", options: ["A hard cap that automatically disables resources once your credit is used, preventing unexpected charges", "A monthly report emailed to the account owner", "A tag applied to all resources", "A feature only available to enterprise agreements"], answer: 0, explanation: "A spending limit, available on certain account types like free trials, automatically stops resource usage once the included credit is exhausted, helping prevent unexpected charges — this is different from a budget, which only alerts rather than blocks." },
  { id: 98, domain: "management", question: "What is Azure Reservations (reserved instances) designed to do?", options: ["Provide a discount on compute costs in exchange for committing to use a resource for a fixed term, such as one or three years", "Guarantee a specific physical server for your exclusive use forever", "Replace the need for a support plan", "Automatically lock resources against deletion"], answer: 0, explanation: "Azure Reservations let you commit to using a resource, such as a VM size, for one or three years in exchange for a significant discount compared to pay-as-you-go pricing." },
  { id: 99, domain: "management", question: "What is Azure Hybrid Benefit?", options: ["A discount that lets you use existing on-premises Windows Server or SQL Server licenses (with Software Assurance) to reduce the cost of running those workloads in Azure", "A free tier for new Azure customers", "A tool for managing hybrid network connections only", "A feature that merges two Azure subscriptions into one"], answer: 0, explanation: "Azure Hybrid Benefit allows organizations to apply existing on-premises licenses covered by Software Assurance toward the cost of equivalent resources in Azure, reducing overall spend." },
  { id: 100, domain: "management", question: "A company wants a single place to view current cost trends, set budgets, get cost-saving recommendations, and see detailed invoices for its Azure subscription. Which service should it use?", options: ["Azure Advisor only", "Azure Cost Management + Billing", "Azure Service Health", "Azure Policy"], answer: 1, explanation: "Azure Cost Management + Billing is the centralized suite for monitoring spend, analyzing cost trends, setting budgets and alerts, viewing invoices, and getting cost optimization insights." },
];

export default questions;
